#include <bits/stdc++.h>
using namespace std;

int MOD;

void dfs1(int u, int parent, vector<vector<int>>& adj, vector<long long>& dp) {
    dp[u] = 1;
    for (int v : adj[u]) {
        if (v == parent) continue;
        dfs1(v, u, adj, dp);
        dp[u] = (dp[u] * (dp[v] + 1)) % MOD;
    }
}

void dfs2(int u, int parent, vector<vector<int>>& adj, vector<long long>& dp, vector<long long>& ans) {
    ans[u] = dp[u];
    int n = adj[u].size();
    vector<long long> pref(n + 1, 1), suff(n + 1, 1);

    for (int i = 0; i < n; i++) {
        int v = adj[u][i];
        if (v == parent) {
            pref[i+1] = pref[i];
        } else {
            pref[i+1] = (pref[i] * (dp[v] + 1)) % MOD;
        }
    }
    for (int i = n-1; i >= 0; i--) {
        int v = adj[u][i];
        if (v == parent) {
            suff[i] = suff[i+1];
        } else {
            suff[i] = (suff[i+1] * (dp[v] + 1)) % MOD;
        }
    }

    for (int i = 0; i < n; i++) {
        int v = adj[u][i];
        if (v == parent) continue;
        long long par_contrib = (pref[i] * suff[i+1]) % MOD;

        long long old_u = dp[u];
        long long old_v = dp[v];

        dp[u] = par_contrib;
        dp[v] = (dp[v] * (dp[u] + 1)) % MOD;

        dfs2(v, u, adj, dp, ans);

        dp[u] = old_u;
        dp[v] = old_v;
    }
}

