int main(){
    int n, M;
    cin >> n >> M;

    vector<vector<int>> adj(n+1);
    for(int i = 0; i < n-1; i++){
        int x, y; cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    vector<long long> down(n+1, 1), up(n+1, 0), ans(n+1, 1);
    vector<int> order, par(n+1, 0);

    // BFS to get order
    vector<bool> visited(n+1, false);
    queue<int> q;
    q.push(1); visited[1] = true; par[1] = 0;
    while(!q.empty()){
        int v = q.front(); q.pop();
        order.push_back(v);
        for(int u : adj[v]) if(!visited[u]){
            visited[u] = true;
            par[u] = v;
            q.push(u);
        }
    }

    // Compute down in reverse BFS order
    for(int i = order.size()-1; i >= 0; i--){
        int v = order[i];
        down[v] = 1;
        for(int u : adj[v]) if(u != par[v]){
            down[v] = (down[v] * ((1 + down[u]) % M)) % M;
        }
    }

    // Compute up in BFS order
    up[1] = 0;
    for(int i = 0; i < (int)order.size(); i++){
        int v = order[i];
        vector<int> children;
        for(int u : adj[v]) if(u != par[v]) children.push_back(u);
        int k = children.size();
        vector<long long> pre(k+1, 1), suf(k+1, 1);
        for(int j = 0; j < k; j++) pre[j+1] = pre[j] * ((1+down[children[j]])%M) % M;
        for(int j = k-1; j >= 0; j--) suf[j] = suf[j+1] * ((1+down[children[j]])%M) % M;
        for(int j = 0; j < k; j++){
            up[children[j]] = (1 + up[v]) % M * pre[j] % M * suf[j+1] % M;
        }
        ans[v] = (1 + up[v]) % M * down[v] % M;
    }

    for(int v = 1; v <= n; v++) cout << ans[v] << "\n";
}

