using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long M;
    cin >> N >> M;

    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int x, y;
        cin >> x >> y;
        g[x].push_back(y);
        g[y].push_back(x);
    }

    vector<int> parent(N + 1, 0), order;
    order.reserve(N);

    // Build rooted tree at 1
    {
        stack<int> st;
        st.push(1);
        parent[1] = -1;
        while (!st.empty()) {
            int v = st.top();
            st.pop();
            order.push_back(v);
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                st.push(to);
            }
        }
    }

    // dpDown[v]:
    // number of valid colorings in subtree of v such that
    // all black vertices in that subtree form one connected component
    // and it contains v (so v is black).
    //
    // For each child, either:
    // - no black vertex in child's subtree: 1 way (all white)
    // - connected black component containing child: dpDown[child] ways
    //
    // Hence dpDown[v] = product(1 + dpDown[child]).
    vector<long long> dpDown(N + 1, 1);

    for (int i = N - 1; i >= 0; --i) {
        int v = order[i];
        long long prod = 1 % M;
        for (int to : g[v]) {
            if (to == parent[v]) continue;
            prod = (prod * ((dpDown[to] + 1) % M)) % M;
        }
        dpDown[v] = prod;
    }

    // ans[v]:
    // number of valid colorings of whole tree such that
    // black vertices form one connected component containing v.
    //
    // Reroot DP:
    // For each neighbor side of v, contribution is:
    // - choose nothing black from that side: 1
    // - choose a connected black component attached through that neighbor: value from that side
    //
    // For child side, value = dpDown[child]
    // For parent side, value = up[v]
    vector<long long> up(N + 1, 0), ans(N + 1, 0);

    // Root has no parent side
    up[1] = 0;

    for (int v : order) {
        int deg = (int)g[v].size();
        vector<long long> val(deg);

        for (int i = 0; i < deg; ++i) {
            int to = g[v][i];
            if (to == parent[v]) val[i] = up[v];
            else val[i] = dpDown[to];
        }

        // ans[v] = product over neighbors of (1 + val)
        vector<long long> pref(deg + 1, 1 % M), suff(deg + 1, 1 % M);
        for (int i = 0; i < deg; ++i) {
            pref[i + 1] = (pref[i] * ((val[i] + 1) % M)) % M;
        }
        for (int i = deg - 1; i >= 0; --i) {
            suff[i] = (suff[i + 1] * ((val[i] + 1) % M)) % M;
        }

        ans[v] = pref[deg];

        // propagate to children
        for (int i = 0; i < deg; ++i) {
            int to = g[v][i];
            if (to == parent[v]) continue;

            // product over all other neighbor sides of v
            long long without_i = (pref[i] * suff[i + 1]) % M;
            // From child's perspective, the parent side contributes a connected
            // black component containing v, counted by without_i.
            up[to] = without_i;
        }
    }

    for (int i = 1; i <= N; ++i) {
        cout << ans[i] % M << '\n';
    }

    return 0;
}

