#define MAXN 200005

typedef struct Edge {
    int to;
    struct Edge *next;
} Edge;

Edge *adj[MAXN];
int N, M;

void add_edge(int u, int v) {
    Edge *e = malloc(sizeof(Edge));
    e->to = v;
    e->next = adj[u];
    adj[u] = e;
}

long long dp[MAXN][2]; // dp[node][0] = ways if node white, dp[node][1] = ways if node black
int parent[MAXN];

void dfs(int u, int p) {
    parent[u] = p;
    dp[u][0] = 1;
    dp[u][1] = 1;
    for (Edge *e = adj[u]; e; e = e->next) {
        int v = e->to;
        if (v == p) continue;
        dfs(v, u);
        // If u is black, child can be black (connected) or white
        dp[u][1] = (dp[u][1] * (dp[v][0] + dp[v][1])) % M;
        // If u is white, child must be white (to not break connectivity from u's perspective)
        dp[u][0] = (dp[u][0] * dp[v][0]) % M;
    }
}

long long result[MAXN];

void reroot(int u, int p, long long up_white, long long up_black) {
    // Compute answer for u fixed as black
    // All possibilities: the whole tree with u black
    long long total_black = dp[u][1];
    // Multiply by contribution from parent side
    if (p != -1) {
        total_black = (total_black * (up_black + up_white)) % M;
    }
    result[u] = total_black;

    // Precompute prefix and suffix products for rerooting
    int deg = 0;
    for (Edge *e = adj[u]; e; e = e->next) {
        if (e->to != p) deg++;
    }
    if (deg == 0) return;

    long long *pref_white = malloc((deg+2) * sizeof(long long));
    long long *pref_black = malloc((deg+2) * sizeof(long long));
    long long *suff_white = malloc((deg+2) * sizeof(long long));
    long long *suff_black = malloc((deg+2) * sizeof(long long));

    int idx = 0;
    long long prod_w = 1, prod_b = 1;
    for (Edge *e = adj[u]; e; e = e->next) {
        int v = e->to;
        if (v == p) continue;
        prod_w = (prod_w * dp[v][0]) % M;
        prod_b = (prod_b * (dp[v][0] + dp[v][1])) % M;
        pref_white[idx] = prod_w;
        pref_black[idx] = prod_b;
        idx++;
    }

    prod_w = 1; prod_b = 1;
    int total = idx;
    for (int i = total-1; i >= 0; i--) {
        int v;
        idx = 0;
        for (Edge *e = adj[u]; e; e = e->next) {
            if (e->to == p) continue;
            if (idx == i) { v = e->to; break; }
            idx++;
        }
        prod_w = (prod_w * dp[v][0]) % M;
        prod_b = (prod_b * (dp[v][0] + dp[v][1])) % M;
        suff_white[i] = prod_w;
        suff_black[i] = prod_b;
    }

    idx = 0;
    for (Edge *e = adj[u]; e; e = e->next) {
        int v = e->to;
        if (v == p) continue;
        long long left_w = (idx > 0) ? pref_white[idx-1] : 1;
        long long left_b = (idx > 0) ? pref_black[idx-1] : 1;
        long long right_w = (idx < total-1) ? suff_white[idx+1] : 1;
        long long right_b = (idx < total-1) ? suff_black[idx+1] : 1;
        long long without_v_white = (left_w * right_w) % M;
        long long without_v_black = (left_b * right_b) % M;

        long long new_up_white, new_up_black;
        if (p == -1) {
            new_up_white = without_v_white;
            new_up_black = without_v_black;
        } else {
            // parent side: up_white -> if parent white, then u must be white
            // up_black -> if parent black, u can be black or white
            long long parent_white_contrib = (up_white * without_v_white) % M;
            long long parent_black_contrib = (up_black * (without_v_white + without_v_black)) % M;
            // For u as white: parent must be white
            new_up_white = parent_white_contrib;
            // For u as black: parent can be white or black? Actually if u is black, parent can be black (connected) or white? If parent white, then u black breaks connectivity unless it's the only black. But in reroot we consider parent side as whole tree outside v's subtree. So:
            new_up_black = (parent_white_contrib + parent_black_contrib) % M;
        }
        reroot(v, u, new_up_white, new_up_black);
        idx++;
    }

    free(pref_white);
    free(pref_black);
    free(suff_white);
    free(suff_black);
}

