    scanf("%d %d", &N, &M);
    for (int i = 0; i < N-1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        add_edge(x, y);
        add_edge(y, x);
    }
    dfs(1, -1);
    reroot(1, -1, 1, 1);
    for (int i = 1; i <= N; i++) {
        printf("%lld\n", result[i]);
    }
    return 0;
}

