    down_dp = (ll*)malloc((N + 1) * sizeof(ll));
    up_dp = (ll*)malloc((N + 1) * sizeof(ll));
    ans = (ll*)malloc((N + 1) * sizeof(ll));

    // iterative DFS to get parent and order
    int *stack = (int*)malloc(N * sizeof(int));
    int top = 0, ord_sz = 0;
    stack[top++] = 1;
    parent_arr[1] = 0;

    while (top) {
        int v = stack[--top];
        order_arr[ord_sz++] = v;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent_arr[v]) continue;
            parent_arr[to] = v;
            stack[top++] = to;
        }
    }

    // bottom-up DP
    for (int i = N - 1; i >= 0; i--) {
        int v = order_arr[i];
        ll prod = 1 % MOD;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent_arr[v]) continue;
            prod = (prod * ((down_dp[to] + 1) % MOD)) % MOD;
        }
        down_dp[v] = prod;
    }

    // top-down reroot DP
    up_dp[1] = 1 % MOD;

    for (int i = 0; i < N; i++) {
        int v = order_arr[i];

        // count children
        int deg_children = 0;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent_arr[v]) continue;
            deg_children++;
        }

        if (deg_children == 0) continue;

        int *children = (int*)malloc(deg_children * sizeof(int));
        ll *vals = (ll*)malloc(deg_children * sizeof(ll));

        int idx = 0;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent_arr[v]) continue;
            children[idx] = to;
            vals[idx] = (down_dp[to] + 1) % MOD;
            idx++;
        }

        ll *pref = (ll*)malloc((deg_children + 1) * sizeof(ll));
        ll *suff = (ll*)malloc((deg_children + 1) * sizeof(ll));

        pref[0] = 1 % MOD;
        for (int j = 0; j < deg_children; j++) {
            pref[j + 1] = (pref[j] * vals[j]) % MOD;
        }

        suff[deg_children] = 1 % MOD;
        for (int j = deg_children - 1; j >= 0; j--) {
            suff[j] = (suff[j + 1] * vals[j]) % MOD;
        }

        for (int j = 0; j < deg_children; j++) {
            int c = children[j];
            ll without_c = (pref[j] * suff[j + 1]) % MOD;
            up_dp[c] = (1 + (up_dp[v] * without_c) % MOD) % MOD;
        }

        free(children);
        free(vals);
        free(pref);
        free(suff);
    }

    for (int v = 1; v <= N; v++) {
        ans[v] = (down_dp[v] * up_dp[v]) % MOD;
    }

    for (int v = 1; v <= N; v++) {
        printf("%lld\n", ans[v]);
    }

    free(head);
    free(edges);
    free(parent_arr);
    free(order_arr);
    free(subsz);
    free(down_dp);
    free(up_dp);
    free(ans);
    free(stack);

    return 0;
}
